    await page.goto('/pos');

    // Verificar que el botón cumple con el área interactiva mínima
    const productButton = page.locator('button[data-testid="pos-product-btn"]').first();
    await expect(productButton).toBeVisible();

    const box = await productButton.boundingBox();
    expect(box?.height).toBeGreaterThanOrEqual(48);
    expect(box?.width).toBeGreaterThanOrEqual(48);

    // Click táctil para agregar al carrito
    await productButton.click();

    // Validar presencia en el CartPanel refactorizado
